css:
:scope{display:block;width:100%}
.pw{--ink:#010A12;--bone:#EDE6D8;--stone:#E0D9CB;--sand:#BBAFA3;--clay:#8C5B46;--head:'Cormorant Garamond',serif;--body:'EB Garamond',serif;--label:'Montserrat',sans-serif;position:relative;font-family:var(--body);font-size:21px;line-height:1.5;font-weight:400;letter-spacing:0;-webkit-font-smoothing:antialiased;text-align:left}
.pw *{box-sizing:border-box}
:where(.pw p,.pw h1,.pw h2,.pw h3){margin:0;padding:0}
:where(.pw p,.pw li,.pw h1,.pw h2,.pw h3){text-wrap:wrap}
:where(.pw h1,.pw h2,.pw h3){color:inherit}
:where(.pw){overflow-wrap:normal}
.kick{margin:0;font-family:var(--label);font-weight:400;font-size:12px;letter-spacing:.32em;text-transform:uppercase;color:var(--sand)}
.rule{width:64px;height:1px;background:var(--clay);border:0;margin:28px 0 32px}
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:52px;font-family:var(--label);font-weight:400;font-size:12px;line-height:1.5;letter-spacing:.26em;text-transform:uppercase;text-decoration:none;padding:0 32px;border:1px solid currentColor;background:transparent;color:inherit;cursor:pointer;transition:background .45s ease,color .45s ease,border-color .45s ease}
.btn.clayline{color:var(--bone);border-color:var(--clay)}
.btn.clayline:hover,.btn.clayline:focus-visible{background:var(--clay);color:var(--bone)}
.btn.boneclay{color:var(--bone);border-color:var(--bone)}
.btn.boneclay:hover,.btn.boneclay:focus-visible{background:var(--clay);border-color:var(--clay);color:var(--bone)}
.btn:focus-visible{outline:2px solid var(--clay);outline-offset:3px}
.book{display:grid;grid-template-columns:1fr 1fr;min-height:760px;background:var(--ink);color:var(--bone)}
.book .photo{position:relative;overflow:hidden;background:#d8cfbf}
.book .photo img,.book .photo picture{position:absolute;inset:0;width:100%;height:100%;max-width:none;object-fit:cover;object-position:46% 38%;display:block}
.book .photo picture img{position:static}
.book .photo .os-img{position:absolute;inset:0;width:100%;height:100%;aspect-ratio:auto;padding:0;border:0;background:none}
.js-rv.book .photo img{transform:scale(1.04);transition:transform 8s ease}
.js-rv.book.on .photo img{transform:scale(1)}
.book .copy{display:flex;flex-direction:column;justify-content:center;padding:160px 9% 160px 8%}
.book h2{font-family:var(--label);font-weight:300;text-transform:uppercase;font-size:min(58px,4.05vw);line-height:1.15;letter-spacing:0;margin:0;white-space:nowrap}
.book h2 .t{display:inline-block;letter-spacing:.26em;margin-left:-.12em}
.book .bsub{margin:26px 0 0;font-family:var(--label);font-weight:300;text-transform:uppercase;font-size:16px;line-height:1.3;color:var(--stone);white-space:nowrap}
.book .bsub .s{display:inline-block;letter-spacing:calc((9.12209 * min(58px, 4.05vw) - 349.4885px) / 34)}
.book .desc{margin:64px 0 0;max-width:26em;color:var(--stone)}
.book .date{margin:28px 0 0;font-family:var(--head);font-weight:500;font-size:28px}
.book .btns{margin-top:40px;display:flex;gap:14px;flex-wrap:wrap}
.js-rv .rv{opacity:0;transform:translateY(16px);transition:opacity 1.3s ease,transform 1.3s ease}
.js-rv .rv.on{opacity:1;transform:none}
.js-rv .d1{transition-delay:.12s}
.js-rv .d2{transition-delay:.24s}
.js-rv .d3{transition-delay:.36s}
.js-rv .d4{transition-delay:.48s}
@media (max-width:1199px){.book .bsub{white-space:normal}.book .bsub .s{display:inline;letter-spacing:.3em}}
@media (max-width:767px){.pw{font-size:19px}.book{grid-template-columns:1fr;min-height:0}.book .photo{aspect-ratio:7/8}.book .copy{padding:88px 20px 88px}.book h2{font-size:34px}.book .bsub{margin-top:18px}.book .desc{margin-top:36px}}
@media (prefers-reduced-motion:reduce){.js-rv .rv{opacity:1;transform:none;transition:none}.js-rv.book .photo img{transform:none;transition:none}}
